String formData = "Jan 25 jan@test.pl\nAnna abc annatest.pl\nBartek 30 bartek@test.pl\n";
Scanner outerScanner = new Scanner(formData);
List<String> valid = new ArrayList<>();
List<String> errors = new ArrayList<>();

while (outerScanner.hasNextLine()) {
    Scanner lineScanner = new Scanner(outerScanner.nextLine());
    String imie = lineScanner.next();
    if (!lineScanner.hasNextInt()) {
        errors.add(imie + ": niepoprawny wiek");
        lineScanner.close();
        continue;
    }
    int wiek = lineScanner.nextInt();
    String email = lineScanner.next();
    if (!email.contains("@")) {
        errors.add(imie + ": niepoprawny email");
    } else {
        valid.add(imie + " (" + wiek + ", " + email + ")");
    }
    lineScanner.close();
}
System.out.println("Poprawne: " + valid);
System.out.println("Bledy: " + errors);
outerScanner.close();

